// ─── Détermine les tests avec assez de données ───────────────────
const rows = $input.all().map(i => i.json);

// Grouper par test_name
const tests = {};
rows.forEach(r => {
  if (!tests[r.test_name]) tests[r.test_name] = {};
  tests[r.test_name][r.variant] = r;
});

// Tests avec les deux variantes ayant >= 15 envois chacune
const readyTests = Object.entries(tests)
  .filter(([, variants]) => variants['A'] && variants['B'] && variants['A'].sends >= 15 && variants['B'].sends >= 15)
  .map(([name, variants]) => ({
    test_name: name,
    variant_a: variants['A'],
    variant_b: variants['B'],
    winner: parseFloat(variants['A'].response_rate_pct || 0) >= parseFloat(variants['B'].response_rate_pct || 0) ? 'A' : 'B',
    delta_response_rate: Math.abs(
      parseFloat(variants['A'].response_rate_pct || 0) - parseFloat(variants['B'].response_rate_pct || 0)
    ).toFixed(1),
    already_decided: false
  }));

if (readyTests.length === 0) {
  return [{ json: { skip: true, reason: 'Aucun test avec assez de données (min 15 envois par variante)' } }];
}

return readyTests.map(t => ({ json: t }));

// ─── Promeut la variante gagnante comme Champion ─────────────────
const test = $input.item.json;
const winner = test.winner;
const loser = winner === 'A' ? 'B' : 'A';
const winnerData = test[`variant_${winner.toLowerCase()}`];
const testName = test.test_name;

// Extraire le type de template depuis le test_name (ex: 'outreach_linkedin_oct2025')
const templateType = testName.split('_').slice(0,2).join('_');

return [{
  json: {
    test_name: testName,
    winner,
    loser,
    winner_template_id: winnerData.template_id,
    loser_variant: loser,
    template_type: templateType,
    winner_rate: winnerData.response_rate_pct,
    delta: test.delta_response_rate,
    promote_sql: `UPDATE message_templates SET is_champion = TRUE, notes = CONCAT(notes, ' | Champion A/B test ${testName} le ${new Date().toISOString().split('T')[0]} (+${test.delta_response_rate}%)') WHERE id = ${winnerData.template_id}`,
    retire_sql: `UPDATE message_templates SET is_active = FALSE, retired_at = NOW(), notes = CONCAT(notes, ' | Retiré A/B test ${testName}') WHERE template_type = '${templateType}' AND variant = '${loser}' AND is_champion = FALSE`
  }
}];

// ─── Discord – Annonce du gagnant A/B ────────────────────────────
const d = $('Prépare promotion gagnant').item.json;
const emoji = parseFloat(d.delta) >= 10 ? '🏆' : '✅';

return [{
  json: {
    embeds: [{
      title: `${emoji} A/B Test terminé – Variante ${d.winner} gagne !`,
      description: `Le test **${d.test_name}** est conclu avec un résultat statistiquement significatif.`,
      color: 3066993,
      fields: [
        { name: '🥇 Variante gagnante', value: `**${d.winner}** — Taux de réponse : **${d.winner_rate}%**`, inline: true },
        { name: '📊 Avantage', value: `+${d.delta}% vs variante ${d.loser}`, inline: true },
        { name: '🔄 Action', value: 'Variante gagnante promue Champion\nVariante perdante retirée\nNouveau challenger généré', inline: false }
      ],
      footer: { text: `A/B Testing Engine • ${new Date().toLocaleDateString('fr-FR')}` },
      timestamp: new Date().toISOString()
    }]
  }
}];

// ─── Routeur A/B : assigne chaque prospect à une variante ─────────
const prospects = $('Fetch prospects pour A/B (DB)').all().map(i => i.json);
const templates = $('Fetch templates actifs (DB)').all().map(i => i.json);

// Organiser les templates par type
const byType = {};
templates.forEach(t => {
  if (!byType[t.template_type]) byType[t.template_type] = {};
  byType[t.template_type][t.variant] = t;
});

let variantCounter = { A: 0, B: 0 };

const assigned = prospects.map((p, idx) => {
  const templateType = p.platform === 'instagram' ? 'outreach_instagram' : 'outreach_linkedin';
  const typeTemplates = byType[templateType] || {};
  const hasB = !!typeTemplates['B'];

  // Split 50/50 : indices pairs → A, impairs → B (si B existe)
  const variant = (hasB && idx % 2 === 1) ? 'B' : 'A';
  const template = typeTemplates[variant] || typeTemplates['A'];

  if (!template) return null;

  const testName = `${templateType}_${new Date().toISOString().slice(0,7)}`;

  return {
    json: {
      ...p,
      _ab: {
        variant,
        template_id: template.id,
        template_type: templateType,
        test_name: testName,
        system_prompt: template.system_prompt,
        user_prompt: template.user_prompt,
        model: template.model
      }
    }
  };
}).filter(Boolean);

console.log(`[WF7] ${assigned.length} prospects assignés (A/B split)`);
return assigned;

// ─── Enregistre l'assignation A/B en DB ──────────────────────────
const item = $input.item.json;
const ab = item._ab;

return [{
  json: {
    sql: `INSERT INTO ab_tests (prospect_id, template_id, test_name, variant, template_type, sent_at)
          VALUES (${item.id}, ${ab.template_id}, '${ab.test_name}', '${ab.variant}', '${ab.template_type}', NOW())
          ON CONFLICT DO NOTHING`,
    prospect: item,
    ab
  }
}];
